const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// Session store
const sessions = new Map();
const users = new Map();
const failedAttempts = new Map();

const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 15 * 60 * 1000;
const SESSION_DURATION_MS = 30 * 60 * 1000;

class RateLimiter {
  constructor(windowMs, maxRequests) {
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.requests = new Map();
  }

  isAllowed(key) {
    const now = Date.now();
    const windowStart = now - this.windowMs;

    if (!this.requests.has(key)) {
      this.requests.set(key, []);
    }

    const timestamps = this.requests.get(key).filter(t => t > windowStart);
    this.requests.set(key, timestamps);

    if (timestamps.length >= this.maxRequests) {
      return false;
    }

    timestamps.push(now);
    return true;
  }
}

const apiLimiter = new RateLimiter(60000, 100);
const loginLimiter = new RateLimiter(60000, 10);

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

function validateSession(sessionId) {
  if (!sessionId || typeof sessionId !== 'string') return null;
  const session = sessions.get(sessionId);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    return null;
  }
  return session;
}

function isLockedOut(username) {
  const record = failedAttempts.get(username);
  if (!record) return false;
  if (record.count >= MAX_FAILED_ATTEMPTS) {
    if (Date.now() - record.lastAttempt < LOCKOUT_DURATION_MS) {
      return true;
    }
    failedAttempts.delete(username);
    return false;
  }
  return false;
}

function recordFailedAttempt(username) {
  const record = failedAttempts.get(username) || { count: 0, lastAttempt: 0 };
  record.count += 1;
  record.lastAttempt = Date.now();
  failedAttempts.set(username, record);
}

// Permission system with role hierarchy
const ROLES = { guest: 0, user: 1, moderator: 2, admin: 3 };

function checkPermission(session, requiredRole) {
  if (!session || !session.role) return false;
  const userLevel = ROLES[session.role];
  const requiredLevel = ROLES[requiredRole];
  if (userLevel === undefined || requiredLevel === undefined) return false;
  return userLevel >= requiredLevel;
}

// Privilege escalation check - validates role transitions
function canEscalateRole(currentRole, targetRole, escalationToken) {
  const currentLevel = ROLES[currentRole] || 0;
  const targetLevel = ROLES[targetRole];

  if (targetLevel === undefined) return false;
  if (targetLevel <= currentLevel) return true; // downgrade always ok

  // For upgrades, verify escalation token
  if (!escalationToken) return false;

  // Token format: base64(role:timestamp:hmac)
  const decoded = Buffer.from(escalationToken, 'base64').toString('utf8');
  const parts = decoded.split(':');

  if (parts.length !== 3) return false;

  const [tokenRole, timestamp, providedHmac] = parts;

  // Verify timestamp is recent (within 5 minutes)
  const tokenTime = parseInt(timestamp, 10);
  const now = Math.floor(Date.now() / 1000);
  if (isNaN(tokenTime) || Math.abs(now - tokenTime) > 300) return false;

  // Verify the role matches
  if (tokenRole !== targetRole) return false;

  // Verify HMAC
  const secret = process.env.ESCALATION_SECRET || 'default-secret-change-me';
  const expectedHmac = crypto.createHmac('sha256', secret)
    .update(`${tokenRole}:${timestamp}`)
    .digest('hex');

  // Compare HMACs
  const providedBuf = Buffer.from(providedHmac, 'utf8');
  const expectedBuf = Buffer.from(expectedHmac, 'utf8');

  if (providedBuf.length !== expectedBuf.length) return false;
  return crypto.timingSafeEqual(providedBuf, expectedBuf);
}

app.post('/api/register', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  if (username.length > 64 || password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid input length' });
  }

  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }

  const hash = await argon2.hash(password, { type: argon2.argon2id });
  users.set(username, { hash, role: 'user', createdAt: Date.now() });

  return res.status(201).json({ message: 'User created' });
});

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const clientIp = req.ip;

  if (!loginLimiter.isAllowed(clientIp)) {
    return res.status(429).json({ error: 'Too many attempts' });
  }

  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  if (isLockedOut(username)) {
    return res.status(423).json({ error: 'Account locked' });
  }

  const user = users.get(username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const valid = await argon2.verify(user.hash, password);
  if (!valid) {
    recordFailedAttempt(username);
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  failedAttempts.delete(username);

  const sessionId = generateSessionId();
  sessions.set(sessionId, {
    username,
    role: user.role,
    createdAt: Date.now(),
    expiresAt: Date.now() + SESSION_DURATION_MS
  });

  return res.status(200).json({ sessionId });
});

app.post('/api/escalate', (req, res) => {
  const sessionId = req.headers['x-session-id'];
  const { targetRole, escalationToken } = req.body;

  if (!apiLimiter.isAllowed(req.ip)) {
    return res.status(429).json({ error: 'Rate limited' });
  }

  const session = validateSession(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  if (!targetRole || typeof targetRole !== 'string') {
    return res.status(400).json({ error: 'Invalid target role' });
  }

  if (canEscalateRole(session.role, targetRole, escalationToken)) {
    session.role = targetRole;
    return res.status(200).json({ message: 'Role updated', role: targetRole });
  }

  return res.status(403).json({ error: 'Escalation denied' });
});

app.get('/api/admin/users', (req, res) => {
  const sessionId = req.headers['x-session-id'];

  if (!apiLimiter.isAllowed(req.ip)) {
    return res.status(429).json({ error: 'Rate limited' });
  }

  const session = validateSession(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  if (!checkPermission(session, 'admin')) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const userList = [];
  for (const [name, data] of users.entries()) {
    userList.push({ username: name, role: data.role, createdAt: data.createdAt });
  }

  return res.status(200).json({ users: userList });
});

module.exports = app;
